<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { getJSON, postJSON } from '../api'
import { canOperate } from '../auth'
import { fmtTime } from '../status'
const route=useRoute()
const rows=ref([]), counts=ref({active:0,counts:{}}), filter=ref('active'), selected=ref(null), visible=ref(false), note=ref(''), busy=ref(false), error=ref('')
const labels={open:'待确认',confirmed:'处理中',awaiting_recheck:'待复检',rechecking:'复检中',closed:'复检通过',false_positive:'已标记误报'}
const actions={opened:'生成告警',observed:'再次发现',confirm:'确认异常',false_positive:'标记误报',resolve:'记录处理结果',note:'补充记录',recheck_started:'发起复检',recheck_passed:'复检通过',recheck_failed:'复检未通过'}
let timer
async function load(){try{const [list,stats]=await Promise.all([getJSON('/api/alerts?status='+filter.value),getJSON('/api/alerts/summary')]);rows.value=list;counts.value=stats;error.value='';if(visible.value&&selected.value)selected.value=await getJSON('/api/alerts/'+selected.value.id)}catch(e){error.value=e.message}}
async function open(id){try{selected.value=await getJSON('/api/alerts/'+id);note.value='';visible.value=true}catch(e){ElMessage.error(e.message)}}
async function act(action){if(!note.value.trim()){ElMessage.warning('请填写处理说明');return}busy.value=true;try{selected.value=await postJSON('/api/alerts/'+selected.value.id+'/actions',{action,note:note.value});note.value='';await load();ElMessage.success('处理记录已保存')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function recheck(){busy.value=true;try{const r=await postJSON('/api/alerts/'+selected.value.id+'/recheck',{robot_id:'robot1'});await load();ElMessage.success('已创建复检任务 '+r.task_no)}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
onMounted(async()=>{await load();if(route.query.alert)await open(route.query.alert);timer=setInterval(load,10000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
 <div class="page-heading"><div><div class="eyebrow">EXCEPTION MANAGEMENT</div><h1>异常处理</h1><p>从发现、处理到复检，让每一个问题都有后续。</p></div><el-button @click="load">↻ 刷新</el-button></div>
 <div class="alert-stats"><div class="surface"><span>待处理告警</span><strong>{{ counts.active }}</strong><small>持续异常合并记录，保留每次发现</small></div><div class="surface"><span>等待复检</span><strong>{{ counts.counts.awaiting_recheck||0 }}</strong><small>处理后需要现场验证</small></div><div class="surface"><span>复检通过</span><strong>{{ counts.counts.closed||0 }}</strong><small>关联复检逐项正常后关闭</small></div></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <section class="surface alert-list"><div class="list-top"><h2>设备异常与待复核事项</h2><el-select v-model="filter" @change="load" style="width:155px"><el-option label="全部待处理" value="active"/><el-option label="全部记录" value=""/><el-option v-for="(name,key) in labels" :key="key" :label="name" :value="key"/></el-select></div>
 <el-table :data="rows" @row-click="r=>open(r.id)" row-class-name="clickable"><el-table-column label="设备 / 观察点" min-width="190"><template #default="{row}"><b>{{ row.equipment_name }}</b><small class="sub">{{ row.equipment_id }} · {{ row.observation_name }}</small></template></el-table-column><el-table-column label="状态" width="118"><template #default="{row}"><span :class="['state',row.status]">{{ labels[row.status] }}</span></template></el-table-column><el-table-column label="判定" width="95"><template #default="{row}">{{ row.kind==='abnormal'?'发现异常':'需人工复核' }}</template></el-table-column><el-table-column prop="summary" label="最新发现" min-width="220" show-overflow-tooltip/><el-table-column prop="occurrences" label="发现次数" width="95"/><el-table-column label="更新时间" width="165"><template #default="{row}">{{ fmtTime(row.updated_at) }}</template></el-table-column><el-table-column width="80"><template #default="{row}"><el-button link type="primary" @click.stop="open(row.id)">处理 ↗</el-button></template></el-table-column><template #empty><div class="empty-state">当前没有符合条件的告警</div></template></el-table>
 </section>
 <el-drawer v-model="visible" size="min(680px, 100vw)" title="告警详情与处理记录"><template v-if="selected"><div class="detail-heading"><span :class="['state',selected.status]">{{ labels[selected.status] }}</span><small>#{{ selected.id }} · {{ selected.equipment_id }}</small><h2>{{ selected.equipment_name }}</h2><p>{{ selected.observation_name }} · 累计发现 {{ selected.occurrences }} 次</p></div><div v-if="selected.evidence" class="evidence"><el-image v-if="selected.evidence.image_url" :src="selected.evidence.image_url" :preview-src-list="[selected.evidence.image_url]" preview-teleported fit="contain"/><p>{{ selected.summary }}</p><router-link :to="'/tasks/'+selected.latest_task_no">查看来源任务 ↗</router-link><div v-for="c in selected.evidence.checks" :key="c.code" class="check"><b>{{ c.name }}</b><span>{{ c.status==='normal'?'正常':c.status==='abnormal'?'异常':'需复核' }}</span><p>{{ c.evidence }}</p></div></div>
 <div v-if="canOperate && !['closed','false_positive'].includes(selected.status)" class="action-box"><h3>处理记录</h3><el-input v-model="note" type="textarea" :rows="3" maxlength="1000" show-word-limit placeholder="填写确认依据、处理措施或误报原因"/><div class="action-buttons"><el-button v-if="selected.status==='open'" :disabled="busy" type="primary" @click="act('confirm')">确认异常</el-button><el-button v-if="['confirmed','awaiting_recheck'].includes(selected.status)" :disabled="busy" type="primary" @click="act('resolve')">保存处理结果</el-button><el-button :disabled="busy" @click="act('note')">补充记录</el-button><el-button v-if="selected.status!=='rechecking'" :disabled="busy" @click="act('false_positive')">标记误报</el-button></div><el-button v-if="selected.status==='awaiting_recheck'" :loading="busy" type="primary" @click="recheck">发起设备复检 ↗</el-button><p v-if="selected.status==='rechecking'">正在等待复检结果。若任务已失败或取消，可重试创建。</p><el-button v-if="selected.status==='rechecking'" :loading="busy" @click="recheck">查看 / 重试复检</el-button></div>
 <div v-if="selected.rechecks.length" class="recheck-list"><h3>关联复检</h3><div v-for="r in selected.rechecks" :key="r.id"><router-link :to="'/tasks/'+r.task_no">{{ r.task_no }} ↗</router-link><small>{{ r.outcome==='passed'?'复检通过':r.outcome==='failed'?'复检未通过':r.task_status==='DONE'?'等待视觉判定':r.task_status }}</small></div></div>
 <h3 class="timeline-title">处理时间线</h3><ol class="alert-timeline"><li v-for="e in selected.events" :key="e.id"><div><b>{{ actions[e.action]||e.action }}</b><time>{{ fmtTime(e.created_at) }}</time></div><small>{{ e.actor }}</small><p v-if="e.note">{{ e.note }}</p><router-link v-if="e.task_no" :to="'/tasks/'+e.task_no">{{ e.task_no }} ↗</router-link></li></ol></template></el-drawer>
</template>
<style scoped>
.alert-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:24px}.alert-stats>div{padding:22px}.alert-stats span,.alert-stats small{display:block;color:#849078;font-size:12px}.alert-stats strong{display:block;font-size:34px;font-weight:550;margin:12px 0;color:#355a44}.alert-stats small{font-size:10px}.alert-list{padding:20px}.list-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.list-top h2{font-size:15px}.sub{display:block;font-size:10px;color:#8b9983;margin-top:6px}.state{display:inline-block;padding:5px 9px;border-radius:5px;background:#f6eadf;color:#a56a46;font-size:11px}.state.closed,.state.false_positive{background:#eaf1e4;color:#63845c}.state.rechecking,.state.awaiting_recheck{background:#eef0dc;color:#828147}.detail-heading{padding-bottom:20px;border-bottom:1px solid #e8eddf}.detail-heading>small{float:right;color:#87977d}.detail-heading h2{font-size:23px;margin:18px 0 8px}.detail-heading p{font-size:12px;color:#8d9b80}.evidence{margin-top:20px}.evidence .el-image{width:100%;max-height:270px;background:#edf1e8;border-radius:7px}.evidence>p{line-height:1.8;font-size:13px}.evidence a,.alert-timeline a,.recheck-list a{font-size:11px;color:#448268}.check{padding:12px;background:#f5f7ef;border-radius:5px;margin-top:10px;font-size:12px}.check span{float:right;color:#a67c51}.check p{font-size:11px;line-height:1.8;color:#7c8d73}.action-box{padding:18px;background:#f4f6ed;margin:24px 0;border-radius:8px}.action-box h3{margin-top:0;font-size:14px}.action-buttons{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.action-buttons .el-button{margin:0}.action-box>p{font-size:11px;line-height:1.8;color:#869477}.recheck-list>div{display:flex;justify-content:space-between;gap:8px;padding:10px 0}.recheck-list small{font-size:10px;color:#839277}.timeline-title,.recheck-list h3{font-size:14px;margin:22px 0}.alert-timeline{list-style:none;padding:0 0 0 15px}.alert-timeline li{border-left:1px solid #d9e3d0;padding:0 0 24px 20px;position:relative}.alert-timeline li:before{content:'';position:absolute;left:-4px;top:4px;width:7px;height:7px;background:#75966d;border-radius:50%}.alert-timeline li>div{display:flex;justify-content:space-between;gap:15px;font-size:12px}.alert-timeline time,.alert-timeline small{font-size:10px;color:#96a18c}.alert-timeline p{font-size:12px;line-height:1.8;color:#748569;white-space:pre-wrap}@media(max-width:750px){.alert-stats{grid-template-columns:1fr}.list-top{gap:12px}.alert-list{padding:12px}}
</style>
